(****************************************************************************)
(* Important basic objects for proofs. *)
(****************************************************************************)

Definition heq : forall {A : Type'}, A -> A -> Prop := @eq.
Definition hex1 : forall {A : Type'}, (A -> Prop) -> Prop := fun A P => exists! x, P x.
Definition not P := ~ P.
Definition hfalse := False.
Definition hor := or.
Definition hex : forall {A : Type'}, (A -> Prop) -> Prop := ex.
Definition hand := and.
Definition htrue := True.

Ltac simptype_in t := eval cbn head in t.
Ltac simptype := match goal with
| H : context [type ?T'] |- _ =>
  let T := simptype_in (type T') in progress (change (type T') with T in H) ; simptype
| |- context [type ?T'] =>
  let T := simptype_in (type T') in progress (change (type T') with T) ; simptype
| _ => idtac end.
Ltac ssrsimpl0 := unfold all, imp, heq, hex1, not, hfalse, hor, hex, hand, htrue in * ;
  simptype.

Lemma fun_ext : forall {a b : Type'} {f g : a -> b}, (forall x, (f x) = (g x)) -> f = g.
Proof. exact @funext. Qed.
Lemma prop_ext : forall {p q : Prop}, (p -> q) -> (q -> p) -> p = q.
Proof. by move=> *; eqProp. Qed.

Arguments point {_}.

Canonical Structure Type'_of_pointed (A : pointedType) := is_Type' (@classical_sets.point A).
(* Tried to also add the reverse one, but the problem arises for choicetype and eqtype:
   if they are defined by default for any Type', then they can be wrongly interpreted for
   nat, list, etc...
   One potential solution would be to only use pointedTypes and hope everything typechecks for
   Types' when closing the module type.
   The theorems would still not be talking about concrete choice instances, but I don't know
   if it would bother anyone (and there is no good solution for it anyway.

   OR: if we really need it, we could change the definition of Type' to also take into account
   the boolean equality and choice.
   The problem would then be that we would need axioms to add Prop and forall instances to this type,
   which would then duplicate with mathcomp classical axioms (since the whole goal of
   Type' is to not have any mathcomp dependency) )
*)

(* Intermediate solution : use pointed : Type' -> pointedType
   This is limited in that generic talk about pointed T
   cannot describe preexisting instances. *)
Definition pointed (T : Type') : Type := T.

HB.instance Definition _ T := gen_eqMixin (pointed T).

HB.instance Definition _ T := gen_choiceMixin (pointed T).

HB.instance Definition _ T := isPointed.Build (pointed T) point.

(* They are convertible, but only for equality (not choice) : *)
Lemma conv_Type'_eq_op (T : pointedType) : @eq_op (pointed T) = @eq_op T.
Proof.
  by (do 2! apply funext=> ?) ; do 2! case: eqP.
Qed.

(* To use for Types that can be infered as pointedTypes or ChoiceBaseAddUMagmas.
   For example, G : zmodType cannot be infered as Type', but G%' can, same for nat%'. *)

Notation "T '%' '":= ltac:(exact (T : pointedType) || exact ((T : Algebra.ChoiceBaseAddUMagma.type) : pointedType)).

Definition COND_dep (Q: Prop) (C: Type) (f1: Q -> C) (f2: ~Q -> C) : C :=
  match pselect Q with
  | left x => f1 x
  | right x => f2 x
  end.

Definition εT T (dflt : T) (P : T -> Prop) : T.
Proof.
  apply (@COND_dep (exists x, P x)).
  - by move/cid=>[].
  - exact (fun=>dflt).
Defined.

Global Definition ε (A : Type') (P : A -> Prop) : A := εT point P.

Coercion asbool : Sortclass >-> bool.

Definition COND (A : Type') (P : Prop) (x y : A) := if P then x else y.

Lemma axiom_0 : forall {A B : Type'}, all (fun t : A -> B => heq (fun x : A => t x) t).
Proof. by []. Qed.

Lemma axiom_1 : forall {A : Type'}, all (fun P : A -> Prop => all (fun x : A => (P x) -> P (@ε A P))).
Proof.
  rewrite/ε/εT/COND_dep=> ???? ; case:pselect => contra ; first by case: cid.
  contradiction contra ; eexists ; eassumption.
Qed.

