Open Scope classical_set_scope.
(* Set min/inf/sup/max are not well developped in mathcomp analysis.
   infimum should correspond to minimal but it's annoying to prove,
   It is easier to use mathcomp's ex_minn. *)

Lemma exists_asboolP1 P : (exists n : nat, P n) -> exists n, `[< P n >].
Proof.
  by case=> n Pn ; exists n ; case: asboolP.
Qed.

Definition minimal (P : num -> Prop) : num :=
  if pselect (exists n, P n) is left H
  then ex_minn (exists_asboolP1 H)
  else 0.

Lemma minimalPexE (P : set nat) (exnP : exists n, P n) :
  minimal P = ex_minn (exists_asboolP1 exnP).
Proof.
  by rewrite/minimal ; case:pselect => // * ; f_equal.
Qed.

Lemma ex_minnPIE (P Q : pred nat) (exnP : ex P) (exnQ : ex Q) :
  P =1 Q -> ex_minn exnP = ex_minn exnQ.
Proof.
  move=> eqPQ ; (do! case:ex_minnP) => n + + m + /[spec n] + + /[spec m].
  rewrite 2!eqPQ => minn minm /minm ? /minn ? ; exact/anti_leq/andP.
Qed.

Lemma minimalbexE (P : pred nat) (exnP : exists n, P n) :
  minimal P = ex_minn exnP.
Proof.
  rewrite minimalPexE ; apply ex_minnPIE => ? ; exact: asboolb.
Qed.

Lemma minimalNexE (P : set nat) : (~ exists n, P n) -> minimal P = 0.
Proof.
  by rewrite/minimal ; case:pselect.
Qed.

Lemma εTNexE (A : Type) (dflt : A) (P : A -> Prop) :
  (~ exists a, P a) -> εT dflt P = dflt.
Proof.
  by rewrite/εT/COND_dep ; case:pselect.
Qed.

Lemma εNexE (A : Type') (P : A -> Prop) : (~exists a, P a) -> ε P = point.
Proof. exact: εTNexE. Qed.

Lemma minimal_def : heq minimal (fun _6536 : num -> Prop => @ε num (fun n : num => hand (_6536 n) (all (fun m : num => (lt m n) -> not (_6536 m))))).
Proof.
  ext => P ; rewrite/0=/minimal ; case: pselect.
  - move=> H ; align_ε.
    + case: ex_minnP => n /asboolP ? minm ; split => // m ltmn /asboolT Pm.
      by have:= (minm _ Pm) ; rewrite leqNgt ltmn.
    + move:(ex_minn _) => n m [Pn minPn] [Pm minPm].
      apply/anti_leq/andP ; rewrite (leqNgt n) (leqNgt m).
      by split ; apply/negP ; firstorder.
  - by move=> exnP ; rewrite εNexE => // -[n [? _]] ; apply exnP ; exists n.
Qed.

Definition WF {A : Type'} : (A -> A -> Prop) -> Prop := @Corelib.Init.Wf.well_founded A.
Lemma WF_def {A : Type'} : heq (@WF A) (fun _6923 : A -> A -> Prop => all (fun P : A -> Prop => (hex (fun x : A => P x)) -> hex (fun x : A => hand (P x) (all (fun y : A => (_6923 y x) -> not (P y)))))).
Proof.
  ext => R H.
  - intros X ne.
    destruct ne as [x Hx].
    rewrite <- (not_notE _); intro goal.
    rewrite/0=. case: (EM (forall y, ~ X y)) => h.
    + assert (~ X x) by exact (h x).
      contradiction.
    + apply h.
      apply (well_founded_induction H).
      intros y g Xy.
      apply goal.
      exists y.
      split; assumption.
  - unfold WF.
    case (EM (forall a : A, Acc R a)); intro h.
    + assumption.
    + rewrite -existsNE in h.
      apply except.
      assert (G: exists x : A, ~ Acc R x /\ (forall y : A, R y x -> ~ ~ Acc R y))
        by apply (H _ h).
      destruct G as [x Gx].
      destruct Gx as [H0 H1].
      apply H0.
      apply Acc_intro.
      intros y Ryx.
      rewrite <- (not_notE _).
      apply H1.
      assumption.
Qed.

