Inductive ZRECSPACE_ind {A : Type'} : (nat -> A -> Prop) -> Prop :=
| ZRECSPACE0 : ZRECSPACE_ind ZBOT
| ZRECSPACE1 c i r : (forall n, ZRECSPACE_ind (r n)) -> ZRECSPACE_ind (ZCONSTR c i r).

Definition ZRECSPACE {A : Type'} : (num -> A -> Prop) -> Prop := ZRECSPACE_ind.
Lemma ZRECSPACE_def {A : Type'} : heq (@ZRECSPACE A) (fun a : num -> A -> Prop => all (fun ZRECSPACE' : (num -> A -> Prop) -> Prop => (all (fun a' : num -> A -> Prop => (hor (heq a' (@ZBOT A)) (hex (fun c : num => hex (fun i : A => hex (fun r : num -> num -> A -> Prop => hand (heq a' (@ZCONSTR A c i r)) (all (fun n : num => ZRECSPACE' (r n)))))))) -> ZRECSPACE' a')) -> ZRECSPACE' a)).
Proof. by ind_align. Qed.

Inductive recspace_ind (A : Type) :=
| BOTTOM_c : recspace_ind A
| CONSTR_c : nat -> A -> (nat -> recspace_ind A) -> recspace_ind A.

Canonical Structure recspace (A : Type') := is_Type' (@BOTTOM_c A).

Definition BOTTOM {A : Type'} : recspace A := BOTTOM_c A.
Definition CONSTR {A : Type'} : num -> A -> (num -> recspace A) -> recspace A := @CONSTR_c A.

Arguments CONSTR [A] _ _ _.
Arguments BOTTOM {A}.

Definition Fnil {A : Type} : nat -> recspace_ind A := fun=> BOTTOM_c A.

Notation "[ ]_rec" := Fnil (format "[ ]_rec").
Notation "[ x ]_rec" := (FCONS x Fnil).
Notation "[ x ; y ; .. ; z ]_rec" := (FCONS x (FCONS y .. (FCONS z Fnil) ..))
  (format "[ '[' x ; '/' y ; '/' .. ; '/' z ']' ]_rec").

Fixpoint hdest_rec {A : Type'} (r : recspace A) : nat -> A -> Prop :=
  match r with
  | BOTTOM_c => ZBOT
  | CONSTR_c n a f => ZCONSTR n a (fun m => hdest_rec (f m)) end.

Definition hmk_rec {A : Type'} : (nat -> A -> Prop) -> recspace A := finv hdest_rec.

Lemma axiom_10 : forall {A : Type'} (r : num -> A -> Prop), heq (@ZRECSPACE A r) (heq (@hdest_rec A (@hmk_rec A r)) r).
Proof.
  intros A P. apply finv_inv_r.
  - induction 1.
    + by exists BOTTOM.
    + exists (CONSTR c i (fun n => hmk_rec (r n))). simpl. f_equal. 
      ext 1 =>n. exact (ε_spec (H0 n)).
  - intros (r , <-). induction r ; now constructor.
Qed.

Lemma hdest_rec_inj {A : Type'} : 
  forall (r r' : recspace A), hdest_rec r = hdest_rec r' -> r = r'.
Proof.
  move:(@thm_INJP_INJ A) (@thm_INJN_INJ A) (@thm_INJF_INJ) (@thm_INJA_INJ).
  move=> /0= INJPI INJNI INJFI INJAI.
  elim=>[|n r recs IHr]; elim=>[|n' r' recs' IHr'] ; rewrite/=/ZBOT/ZCONSTR.
  all: rewrite INJPI INJNI // =>-[].
  1,2: inversion 1.
  rewrite INJPI INJFI INJAI => [= ->] [->] /gen_fun1 rec_eq ; f_equal.
  move=> /1` ? ; exact: IHr.
Qed.

Lemma axiom_9 : forall {A : Type'} (a : recspace A), heq (@hmk_rec A (@hdest_rec A a)) a.
Proof. finv_inv_l ; exact hdest_rec_inj. Qed.

