Canonical Structure Sum (A B : Type') := {|
  type := sum A B ;
  point := inl point
|}.

Definition hdest_sum : forall {A B : Type'}, sum A B -> recspace (prod A B) :=
fun A B p => match p with
| inl a => CONSTR (NUMERAL 0) (a , ε (fun _ => True)) []_rec
| inr b => CONSTR (S (NUMERAL 0)) (ε (fun _ => True) , b) []_rec
end.

Definition hmk_sum {A B : Type'} := finv (@hdest_sum A B).

Lemma axiom_11 {A B : Type'} : forall (a : sum A B), (@hmk_sum A B (@hdest_sum A B a)) = a.
Proof. _mk_dest_inductive. Qed.

Lemma axiom_12 : forall {A B : Type'} (r : recspace (hprod A B)), heq ((fun a : recspace (hprod A B) => all (fun sum' : (recspace (hprod A B)) -> Prop => (all (fun a' : recspace (hprod A B) => (hor (hex (fun a'' : A => heq a' ((fun a''' : A => @CONSTR (hprod A B) (NUMERAL h0) (@hpair A B a''' (@ε B (fun v : B => htrue))) (fun n : num => @BOTTOM (hprod A B))) a''))) (hex (fun a'' : B => heq a' ((fun a''' : B => @CONSTR (hprod A B) (SUC (NUMERAL h0)) (@hpair A B (@ε A (fun v : A => htrue)) a''') (fun n : num => @BOTTOM (hprod A B))) a'')))) -> sum' a')) -> sum' a)) r) (heq (@hdest_sum A B (@hmk_sum A B r)) r).
Proof. by _dest_mk_inductive. Qed.

Definition INL {A B : Type'} : A -> Sum A B := inl.
Lemma INL_def {A B : Type'} : heq (@INL A B) (fun a : A => @hmk_sum A B ((fun a' : A => @CONSTR (hprod A B) (NUMERAL h0) (@hpair A B a' (@ε B (fun v : B => htrue))) (fun n : num => @BOTTOM (hprod A B))) a)).
Proof. constr_align (@axiom_11 A B). Qed.

Definition INR {A B : Type'} : B -> Sum A B := inr.
Lemma INR_def {A B : Type'} : heq (@INR A B) (fun a : B => @hmk_sum A B ((fun a' : B => @CONSTR (hprod A B) (SUC (NUMERAL h0)) (@hpair A B (@ε A (fun v : A => htrue)) a') (fun n : num => @BOTTOM (hprod A B))) a)).
Proof. constr_align (@axiom_11 A B). Qed.

