(****************************************************************************)
(* Alignment of the option type constructor. *)
(****************************************************************************)

Canonical Structure hoption (A : Type') := is_Type' (@None A).

Definition hdest_option : forall {A : Type'}, hoption A -> recspace A :=
  fun A o =>
    match o with
    | None => CONSTR (NUMERAL 0) (ε (fun _ => True)) []_rec
    | Some a => CONSTR (S (NUMERAL 0)) a []_rec
    end.

