(****************************************************************************)
(* Alignment of the seq type constructor. *)
(****************************************************************************)

Canonical Structure hlist (A : Type') := is_Type' (Nil A).

Fixpoint hdest_list {A : Type'} s : recspace A :=
  match s with
  | [::] => CONSTR 0 (ε (fun _ => True)) []_rec
  | a::s => CONSTR 1 a [hdest_list s]_rec
  end.

Definition hmk_list A := finv (@hdest_list A).

Lemma axiom_15 : forall {A : Type'} (a : hlist A), heq (@hmk_list A (@hdest_list A a)) a.
Proof. _mk_dest_inductive. Qed.
