Definition prime : num -> Prop := prime.

Lemma prime_def : heq prime (fun h32188 : num => hand (not (heq h32188 (NUMERAL (BIT1 h0)))) (all (fun x : num => (num_divides x h32188) -> hor (heq x (NUMERAL (BIT1 h0))) (heq x h32188)))).
